import { useState, useCallback, useRef } from 'react';
import MessageList from '@/components/MessageList';
import PromptInput from '@/components/PromptInput';
import EmptyState from '@/components/EmptyState';

type Message = {
  id: string;
  role: 'user' | 'assistant';
  content: string;
};

export default function Home() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  const addMessage = useCallback((role: Message['role'], content: string) => {
    setMessages(prev => [...prev, { id: Math.random().toString(36).substring(2, 9), role, content }]);
  }, []);

  const handleSend = useCallback(async (userMessage: string) => {
    // Add user message
    addMessage('user', userMessage);
    setIsLoading(true);

    // Simulate streaming response
    try {
      // Mock streaming by typing out a response character by character
      const mockResponse = `This is a simulated streaming response to your message: "${userMessage}". 
In a real application, this would be replaced with an actual API call to a language model.
We're simulating a delay to show the streaming effect.`;

      let displayedContent = '';
      for (let i = 0; i < mockResponse.length; i++) {
        // Wait for a short time to simulate typing
        await new Promise(resolve => setTimeout(resolve, 20));
        displayedContent += mockResponse[i];
        // Update the last message (assistant) with the current displayed content
        setMessages(prev => {
          const newMessages = [...prev];
          if (newMessages.length > 0 && newMessages[newMessages.length - 1].role === 'assistant') {
            newMessages[newMessages.length - 1].content = displayedContent;
          } else {
            newMessages.push({ id: Math.random().toString(36).substring(2, 9), role: 'assistant', content: displayedContent });
          }
          return newMessages;
        });
      }
    } finally {
      setIsLoading(false);
    }
  }, [addMessage]);

  return (
    <div className="flex flex-col">
      {messages.length === 0 && !isLoading ? (
        <EmptyState />
      ) : (
        <>
          <MessageList messages={messages} />
          {isLoading && (
            <div className="flex p-4 border-t border-gray-200 dark:border-gray-700 justify-center">
              <div className="animate-pulse h-4 w-4 rounded-full bg-blue-500"></div>
            </div>
          )}
          <PromptInput onSend={handleSend} disabled={isLoading} />
        </>
      )}
    </div>
  );
}
'''.strip())
    print('Created app/page.tsx')

